// Light and dark, from the design system. src/styles/design-system/ is generated by the build
// framework's scripts/design-system.mjs from the design system build/framework.json names; this test
// reads what was generated, never colour values of its own:
//   - the design system's own pairs (tokens.json contrast.pairs) meet their minimum in both themes,
//     and its documented exceptions (contrast.known) are reported;
//   - the role pairs this app's CSS uses (styles/base.css) meet WCAG 2.2 AA in both themes: text
//     4.5:1 (1.4.3), control edges and focus indicators 3:1 (1.4.11, 2.4.11);
//   - both dark blocks (system preference, reader's choice) are identical and every theme has every token;
//   - the app's own styles and components hold no colour values, and use only roles tokens.css defines;
//   - the files come from the design system build/framework.json names.
// Add a pair to APP_PAIRS whenever a component puts a role on another.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { resolve, dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const web = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const generated = join(web, 'src', 'styles', 'design-system');
const tokens = JSON.parse(readFileSync(join(generated, 'tokens.json'), 'utf8'));
const css = readFileSync(join(generated, 'tokens.css'), 'utf8');

// [foreground role, background role, minimum]: what styles/base.css puts on what.
const APP_PAIRS = [
  ['text', 'background', 4.5], ['text', 'surface', 4.5], ['text', 'surfaceSubtle', 4.5],
  ['textMuted', 'background', 4.5], ['textMuted', 'surface', 3], ['textMuted', 'surfaceSubtle', 3],
  ['link', 'background', 4.5], ['linkHover', 'background', 4.5],
  ['textInverse', 'accent', 4.5], ['textInverse', 'accentHover', 4.5], ['accent', 'background', 3],
  ['danger', 'background', 4.5],
  ['focus', 'background', 3], ['focus', 'surface', 3], ['focus', 'surfaceSubtle', 3]
];

/** The custom properties declared in the first block that follows a selector. */
function block(selector) {
  const start = css.indexOf(selector);
  assert.notEqual(start, -1, `tokens.css has no ${selector}`);
  const open = css.indexOf('{', start);
  const body = css.slice(open + 1, css.indexOf('}', open));
  return Object.fromEntries([...body.matchAll(/--([\w-]+)\s*:\s*([^;]+);/g)].map((m) => [m[1], m[2].trim()]));
}

function luminance(hex) {
  const value = hex.replace('#', '');
  assert.match(value, /^([0-9a-f]{3}|[0-9a-f]{6})$/i, `${hex} is an opaque hex colour`);
  const full = value.length === 3 ? [...value].map((c) => c + c).join('') : value;
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(full.slice(i, i + 2), 16) / 255)
    .map((c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

export function contrast(a, b) {
  const [l1, l2] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (l1 + 0.05) / (l2 + 0.05);
}

/** Files under a folder, skipping the generated design system and build output. */
function files(folder) {
  return readdirSync(folder).flatMap((name) => {
    const path = join(folder, name);
    if (['node_modules', 'design-system', 'dist'].includes(name)) return [];
    return statSync(path).isDirectory() ? files(path) : [path];
  });
}

test('the contrast formula matches WCAG for black on white', () => {
  assert.equal(Math.round(contrast('#000000', '#ffffff')), 21);
});

for (const theme of ['light', 'dark']) {
  test(`${theme}: the design system's own pairs meet their minimum`, (t) => {
    const values = tokens.themes[theme];
    for (const pair of tokens.contrast.pairs) {
      if (pair.themes && !pair.themes.includes(theme)) continue;
      assert.ok(values[pair.fg] && values[pair.bg], `${pair.fg} and ${pair.bg} are tokens`);
      const ratio = contrast(values[pair.fg], values[pair.bg]);
      assert.ok(ratio >= pair.min, `${theme}: ${pair.fg} on ${pair.bg} is ${ratio.toFixed(2)}:1, needs ${pair.min}:1`);
    }
    for (const pair of tokens.contrast.known ?? []) {
      t.diagnostic(`known exception in the design system: ${pair.fg} on ${pair.bg} below ${pair.min}:1 (${pair.reason})`);
    }
  });

  test(`${theme}: the roles this app's CSS pairs up meet WCAG 2.2 AA`, () => {
    const roles = tokens.roles[theme];
    for (const [fg, bg, min] of APP_PAIRS) {
      assert.ok(roles[fg] && roles[bg], `the design system maps the roles ${fg} and ${bg}`);
      const ratio = contrast(roles[fg], roles[bg]);
      assert.ok(ratio >= min, `${theme}: ${fg} on ${bg} is ${ratio.toFixed(2)}:1, needs ${min}:1`);
    }
  });
}

test('both dark blocks hold the same tokens, and every theme has every token', () => {
  const light = block(':root {');
  const dark = block(':root[data-theme="dark"]');
  const darkBySystem = block(':root:not([data-theme="light"])');
  assert.deepEqual(darkBySystem, dark);
  assert.deepEqual(Object.keys(dark).sort(), Object.keys(light).sort());
});

test("the app's own styles and components hold no colour values, and use only defined roles", () => {
  const defined = new Set([...css.matchAll(/(--[\w-]+)\s*:/g)].map((m) => m[1]));
  const literal = /(?<![\w&/])#(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})\b|\b(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch)\(/gi;
  const found = [];
  for (const path of [...files(join(web, 'src')), ...files(join(web, 'portal')), join(web, 'index.html')]) {
    if (!/\.(css|tsx?|html)$/.test(path)) continue;
    const text = readFileSync(path, 'utf8');
    const name = relative(web, path).split(sep).join('/');
    for (const match of text.matchAll(literal)) found.push(`${name}: ${match[0]}`);
    for (const [, used] of text.matchAll(/var\((--ds-[\w-]+)/g)) if (!defined.has(used)) found.push(`${name}: ${used} is not in tokens.css`);
  }
  assert.deepEqual(found, [], 'colours come from the design system (styles/design-system/tokens.css), by role');
});

test('the generated files come from the design system build/framework.json names', () => {
  const configPath = resolve(web, '..', '..', 'build', 'framework.json');
  assert.ok(existsSync(configPath), 'build/framework.json records the design system (designSystem.id)');
  const config = JSON.parse(readFileSync(configPath, 'utf8'));
  const id = config.designSystem?.id;
  assert.ok(id, 'build/framework.json has designSystem.id');
  assert.equal(tokens.designSystem.id, id, `src/styles/design-system was generated from '${tokens.designSystem.id}', but build/framework.json says '${id}': regenerate (design-system skill)`);
  assert.ok(css.includes(`design-systems/${id} `), `tokens.css was generated from another design system than '${id}': regenerate`);
});
